    if (sk.length !== fk.length) { rows.push({ label: label + ' — layers', d: `code ${sk.length} · Figma ${fk.length}`, worst: 999 }); return; }
    sk.forEach((k, i) => walk(k, fk[i], trail.concat(s.cls0 || s.name)));
